using Sde.Core;


namespace Sde.Interop.Tests;

/// <summary>
/// The legacy .xls reader and the shapefile-attribute (.dbf) reader. The fixtures are generated by
/// tools/fixtures/make_xls.py and tools/fixtures/make_dbf.py from invented data.
/// </summary>
public class XlsAndDbfTests
{
	private static string Sheets(string name) => Path.Combine(TestPaths.Root, "tests", "fixtures", "sheets", name);

	private static string WideFixture(string name) => Path.Combine(TestPaths.Root, "tests", "fixtures", "accela", name);

	// ───────────────────────── .xls ─────────────────────────

	[Fact]
	public void Xls_SheetNamesAndHeaders()
	{
		string path = Sheets("parcels.xls");
		Assert.Equal(new[] { "Parcels", "Other" }, EnterpriseImport.SheetNames(path));

		// The sheet starts two rows down and one column in; the header is the first filled row.
		SourceTable table = EnterpriseImport.ReadTable(path);
		Assert.Equal("Parcels", table.SheetName);
		Assert.Equal(new[] { "Owner", "Address", "City", "ST", "County", "Zip", "Lat", "Lon", "Year", "Panel Date", "Inspected", "Vacant", "Notes", "SqFt" }, table.Columns);
		Assert.Equal(3, table.Rows.Count);               // the blank row is left out
		Assert.Equal(new[] { 4, 5, 7 }, table.Rows.Select(r => r.RowNumber));
	}

	[Fact]
	public void Xls_TextNumberDateAndEmptyCellsReadLikeXlsx()
	{
		SourceTable table = EnterpriseImport.ReadTable(Sheets("parcels.xls"));
		SourceRow doe = table.Rows[0];
		Assert.Equal("Doe, John", doe[table.IndexOf("Owner")]);
		Assert.Equal("Café on the corner", doe[table.IndexOf("Notes")]);
		Assert.Equal("39.1031", doe[table.IndexOf("Lat")]);
		Assert.Equal("-84.512", doe[table.IndexOf("Lon")]);
		Assert.Equal("1962", doe[table.IndexOf("Year")]);
		Assert.Equal("1450.5", doe[table.IndexOf("SqFt")]);
		Assert.Equal("05012", doe[table.IndexOf("Zip")]);                          // a zero-padded number format keeps its padding
		Assert.Equal("2015-09-30", doe[table.IndexOf("Panel Date")]);              // a date is an ISO date
		Assert.Equal("2026-10-07 14:30:00", doe[table.IndexOf("Inspected")]);      // with a time of day, date and time
		Assert.Equal("TRUE", doe[table.IndexOf("Vacant")]);

		SourceRow smith = table.Rows[1];
		Assert.Equal("43703", smith[table.IndexOf("Zip")]);
		Assert.Equal("FALSE", smith[table.IndexOf("Vacant")]);
		foreach (string empty in new[] { "Lat", "Lon", "Year", "Panel Date", "Inspected", "Notes", "SqFt" })
		{
			Assert.Equal("", smith[table.IndexOf(empty)]);
		}

		SourceRow roe = table.Rows[2];
		Assert.Equal("45402", roe[table.IndexOf("Zip")]);                          // text stays text
		Assert.Equal("", roe[table.IndexOf("Vacant")]);
	}

	[Fact]
	public void Xls_NamedSecondSheet_AndHeaderlessRead()
	{
		string path = Sheets("parcels.xls");
		SourceTable other = EnterpriseImport.ReadTable(path, "other");
		Assert.Equal("Other", other.SheetName);
		Assert.Equal(new[] { "Name", "Value" }, other.Columns);
		Assert.Equal(new[] { "alpha", "7" }, other.Rows.Single().Values);

		SourceTable plain = EnterpriseImport.ReadTable(path, "Other", firstRowIsHeader: false);
		Assert.Equal(new[] { "Column1", "Column2" }, plain.Columns);
		Assert.Equal(2, plain.Rows.Count);

		ArgumentException missing = Assert.Throws<ArgumentException>(() => EnterpriseImport.ReadTable(path, "Nope"));
		Assert.Contains("'Parcels', 'Other'", missing.Message);
	}

	[Fact]
	public void Xls_EnterpriseImport_EndToEnd()
	{
		using TempDatabase t = new TempDatabase();
		EnterpriseMapping m = new EnterpriseMapping
		{
			FirstNameParsing = NameParsing.LastCommaFirst,
			LastNameParsing = NameParsing.LastCommaFirst,
			StreetNumberParsing = StreetNumberParsing.NumberNameSuffix,
		};
		m[EnterpriseField.OwnerFirstName] = "Owner";
		m[EnterpriseField.OwnerLastName] = "Owner";
		m[EnterpriseField.StreetNumber] = "Address";
		m[EnterpriseField.City] = "City";
		m[EnterpriseField.State] = "ST";
		m[EnterpriseField.County] = "County";
		m[EnterpriseField.Zip] = "Zip";
		m[EnterpriseField.Latitude] = "Lat";
		m[EnterpriseField.Longitude] = "Lon";
		m[EnterpriseField.TotalSquareFootage] = "SqFt";
		m[EnterpriseField.YearOfConstruction] = "Year";
		m[EnterpriseField.FirmPanelDate] = "Panel Date";

		SourceTable table = EnterpriseImport.ReadTable(Sheets("parcels.xls"));
		EnterprisePreview preview = EnterpriseImport.Preview(table, m, t.Store.Reference);
		Assert.Empty(preview.MappingProblems);
		Assert.Equal(3, preview.Rows.Count);
		Assert.All(preview.Rows, r => Assert.True(r.IsValid));

		Core.Records.PropertyRecord doe = preview.Rows[0].Property;
		Assert.Equal(("John", "Doe"), (doe.OwnerFirstName, doe.OwnerLastName));
		Assert.Equal("05012", doe.ZipCode);
		Assert.Equal((39.1031m, -84.512m), (doe.Latitude, doe.Longitude));
		Assert.Equal(1962, doe.YearOfConstruction);
		Assert.Equal(new DateTime(2015, 9, 30), doe.FIRMPanelDate);

		int before = t.Store.GetProperties().Count;
		Assert.Equal(3, EnterpriseImport.Import(t.Store, preview));
		Assert.Equal(before + 3, t.Store.GetProperties().Count);
	}

	[Fact]
	public void Xls_InspectionExport_ReadsTheSameAsTheCsvAndImportsTheSame()
	{
		SourceTable csv = SourceTable.Read(WideFixture("inspections-wide.csv"));
		SourceTable xls = SourceTable.Read(WideFixture("inspections-wide.xls"));
		Assert.Equal("Inspections", xls.SheetName);
		Assert.Equal(csv.Columns, xls.Columns);
		Assert.Equal(csv.Rows.Count, xls.Rows.Count);
		for (int i = 0; i < csv.Rows.Count; i++)
		{
			Assert.Equal(csv.Rows[i].RowNumber, xls.Rows[i].RowNumber);
			Assert.Equal(csv.Rows[i].Values, xls.Rows[i].Values);
		}

		using TempDatabase t = new TempDatabase();
		SourceProfile profile = SourceImportTests.Profile(xls);
		SourcePreview preview = SourceImport.Preview(SourceTable.Shape(xls, profile), profile, t.Store);
		Assert.Empty(preview.MappingProblems);
		Assert.Equal(3, preview.Count(ImportRowStatus.NewStructure));
		SourceImportResult result = SourceImport.Import(t.Store, preview, WideFixture("inspections-wide.xls"));
		Assert.Equal((3, 0, 0), (result.Created, result.Updated, result.Unchanged));
	}

	// ───────────────────────── .dbf ─────────────────────────

	[Fact]
	public void Dbf_FieldsAndValues()
	{
		string path = Sheets("parcels.dbf");
		Assert.Equal(new[] { "parcels" }, EnterpriseImport.SheetNames(path));
		SourceTable table = EnterpriseImport.ReadTable(path);

		// The memo field NOTES is left out; the deleted record (file record 2) is skipped.
		Assert.Equal(new[] { "PARCEL", "OWNER", "ACRES", "YEAR", "VALUE", "SALEDATE", "VACANT" }, table.Columns);
		Assert.Equal(3, table.Rows.Count);
		Assert.Equal(new[] { 2, 4, 5 }, table.Rows.Select(r => r.RowNumber));   // counting the header row, as for a .csv

		Assert.Equal(new[] { "0123-0045-0067", "Pat Example", "0.25", "1962", "145000.5", "2015-09-30", "TRUE" }, table.Rows[0].Values);
		Assert.Equal(new[] { "0123-0045-0070", "Renée Café", "12.5", "1978", "210000", "2019-03-01", "FALSE" }, table.Rows[1].Values);   // Windows-1252
		Assert.Equal(new[] { "0145-0001-0001", "Blank Numbers", "", "", "", "", "" }, table.Rows[2].Values);
	}

	[Fact]
	public void Dbf_Utf8_FromSiblingCpg_AndShpPathReadsTheDbf()
	{
		SourceTable viaDbf = EnterpriseImport.ReadTable(Sheets("parcels-utf8.dbf"));
		Assert.Equal("Renée Café", viaDbf.Rows[1][viaDbf.IndexOf("OWNER")]);

		SourceTable viaShp = EnterpriseImport.ReadTable(Sheets("parcels-utf8.shp"));
		Assert.Equal("parcels-utf8", viaShp.SheetName);
		Assert.Equal(viaDbf.Columns, viaShp.Columns);
		Assert.Equal(viaDbf.Rows.Select(r => r.Values), viaShp.Rows.Select(r => r.Values));
	}

	[Fact]
	public void Dbf_CodePageFromLanguageDriverByte()
	{
		SourceTable table = EnterpriseImport.ReadTable(Sheets("cyrillic.dbf"));
		Assert.Equal(new[] { "Привет мир", "7" }, table.Rows.Single().Values);
	}

	[Fact]
	public void Dbf_HeaderlessReadKeepsFieldNamesAsFirstRow_AndShapefileWithoutTable_Fails()
	{
		SourceTable plain = EnterpriseImport.ReadTable(Sheets("cyrillic.dbf"), null, firstRowIsHeader: false);
		Assert.Equal(new[] { "Column1", "Column2" }, plain.Columns);
		Assert.Equal(new[] { "NAME", "ID" }, plain.Rows[0].Values);

		using TempDatabase t = new TempDatabase();
		string lonely = Path.Combine(t.Folder, "lonely.shp");
		File.WriteAllBytes(lonely, new byte[100]);
		FileNotFoundException ex = Assert.Throws<FileNotFoundException>(() => EnterpriseImport.ReadTable(lonely));
		Assert.Contains("no 'lonely.dbf'", ex.Message);
	}

	[Fact]
	public void Dbf_ThatIsNotADbf_Fails()
	{
		using TempDatabase t = new TempDatabase();
		string bad = Path.Combine(t.Folder, "bad.dbf");
		File.WriteAllText(bad, "this is a text file, not a dBASE table, though it is long enough to read");
		Assert.Throws<InvalidDataException>(() => EnterpriseImport.ReadTable(bad));
	}

	[Fact]
	public void UnknownExtension_StillRefused()
	{
		NotSupportedException ex = Assert.Throws<NotSupportedException>(() => EnterpriseImport.ReadTable("/tmp/notes.docx"));
		Assert.Contains("notes.docx", ex.Message);
	}
}
